(() => {
'use strict';
const $=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];
const motionAllowed=()=>!document.body.classList.contains('motion-off')&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&document.documentElement.dataset.motion!=='subtle';
const safeSession={get(k){try{return sessionStorage.getItem(k)}catch{return null}},set(k,v){try{sessionStorage.setItem(k,v)}catch{}},remove(k){try{sessionStorage.removeItem(k)}catch{}}};
const skip=document.createElement('a');skip.className='skip-link';skip.href='#main-content';skip.textContent='Skip to content';document.body.prepend(skip);$('main').id='main-content';
$$('header nav a').forEach(a=>{if(new URL(a.href).pathname===location.pathname)a.setAttribute('aria-current','page')});
const curtain=document.createElement('div');curtain.className='route-curtain';curtain.setAttribute('aria-hidden','true');curtain.textContent='FOCUSED ON TOM';document.body.append(curtain);
if(safeSession.get('tom-transition')&&motionAllowed()){safeSession.remove('tom-transition');curtain.classList.add('arriving');setTimeout(()=>curtain.classList.remove('arriving'),700)}
let navigating=false;
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||a.target||a.hasAttribute('download'))return;const target=new URL(a.href);if(target.origin!==location.origin||target.pathname===location.pathname||!motionAllowed())return;event.preventDefault();if(navigating)return;navigating=true;curtain.textContent=target.pathname.includes('lens')?'BEHIND THE LENS':target.pathname.includes('code')?'INSIDE THE CODE':target.pathname.includes('grid')?'OFF THE GRID':'FOCUSED ON TOM';curtain.dataset.transition=target.pathname.includes('lens')?'lens':target.pathname.includes('code')?'code':target.pathname.includes('grid')?'outside':'home';curtain.classList.remove('arriving');curtain.classList.add('leaving');safeSession.set('tom-transition','1');setTimeout(()=>location.assign(target.href),380)});
addEventListener('pageshow',()=>{navigating=false;curtain.classList.remove('leaving')});
// Subtle pointer lighting and depth, without taking over the native cursor.
if(matchMedia('(pointer:fine)').matches){$$('.world-card,.project-tile').forEach(card=>{card.addEventListener('pointermove',e=>{if(!motionAllowed())return;const r=card.getBoundingClientRect();card.style.setProperty('--mx',`${e.clientX-r.left}px`);card.style.setProperty('--my',`${e.clientY-r.top}px`)});});const title=$('.hero-title');if(title){title.addEventListener('animationend',()=>{title.style.animation='none'},{once:true});$('.hero').addEventListener('pointermove',e=>{if(motionAllowed())title.style.transform=`translate(${(e.clientX-innerWidth/2)*.012}px,${(e.clientY-innerHeight/2)*.01}px)`});$('.hero').addEventListener('pointerleave',()=>title.style.transform='')}}
let raf=false;function scrollEffects(){const bg=$('.chapter-bg');if(bg)bg.style.transform=motionAllowed()&&scrollY<innerHeight*1.2?`translateY(${scrollY*.18}px)`:'none';raf=false}addEventListener('scroll',()=>{if(!raf){raf=true;requestAnimationFrame(scrollEffects)}},{passive:true});
const sectionLinks=$$('.chapter-nav a');if(sectionLinks.length){const spy=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){sectionLinks.forEach(a=>a.setAttribute('aria-current',String(a.hash==='#'+entry.target.id)))}})},{rootMargin:'-15% 0px -65% 0px',threshold:0});sectionLinks.forEach(a=>{const el=$(a.hash);if(el)spy.observe(el)})}
function animateSwap(el){el.classList.remove('content-swap');void el.offsetWidth;if(motionAllowed())el.classList.add('content-swap')}
function selectButtons(selector,selected){$$(selector).forEach(b=>{const active=b===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
// PHOTO WORLD
if($('#legacy-study-image')){
 let grade='natural',original=false;
 const crop=$('#crop'),exposure=$('#exposure'),image=$('#study-image');
 const filters={natural:'saturate(1)',cinema:'saturate(.55) contrast(1.2) sepia(.12)',mono:'grayscale(1) contrast(1.2)',warm:'sepia(.35) saturate(1.35) contrast(1.05)'};
 const names={natural:'Natural',cinema:'Cinema',mono:'Mono',warm:'Golden'};
 function render(){const zoom=Number(crop.value)/10,ev=Number(exposure.value)/10;image.style.transform=`scale(${original?1:zoom})`;image.style.filter=original?'none':`${filters[grade]} brightness(${Math.pow(2,ev)})`;$('#zoom-readout').textContent=(original?1:zoom).toFixed(1)+'×';$('#crop-value').textContent=zoom.toFixed(1)+'×';$('#exposure-value').textContent=(ev>0?'+':'')+ev.toFixed(1);$('#preset-name').textContent=names[grade];$('#grade-readout').textContent=original?'ORIGINAL / REFERENCE STUDY':names[grade].toUpperCase()+' / REFERENCE STUDY';$('#compare').textContent=original?'Return to edit':'Show original';$('#compare').setAttribute('aria-pressed',String(original))}
 $$('#grade-controls button').forEach(b=>b.addEventListener('click',()=>{grade=b.dataset.grade;original=false;selectButtons('#grade-controls button',b);render()}));
 [crop,exposure].forEach(i=>i.addEventListener('input',()=>{original=false;render()}));$('#compare').addEventListener('click',()=>{original=!original;render()});$('#reset-study').addEventListener('click',()=>{grade='natural';original=false;crop.value='10';exposure.value='0';selectButtons('#grade-controls button',$('[data-grade="natural"]'));render()});render();
 const gear={body:['α6700','Sony A6700','The center of my photography setup. It goes from wildlife to automotive work and video, depending on the lens and what I’m out to capture.','THE BODY / PHOTO + VIDEO'],wide:['10—18','Sigma 10–18mm f/2.8','The wide perspective in my bag. A way to fit more of a landscape or environment into the frame and make the surroundings part of the story.','THE WIDE VIEW'],everyday:['17—70','Tamron 17–70mm f/2.8','My flexible everyday zoom. It bridges a wider scene and a closer look without changing lenses every time the subject changes.','THE EVERYDAY PERSPECTIVE'],tele:['200—600','Sony 200–600mm','For wildlife and the details far beyond arm’s reach. Working at the long end has me learning about shutter speed, stability, and getting a genuinely sharp frame. I also have a Sony 70–200mm in the kit.','THE LONG VIEW / WILDLIFE'],film:['MOTION','Beyond the still frame','A DJI Mini 4 Pro for a different vantage point, an Osmo Pocket 3, action cameras, and audio gear. I like putting together short cinematic sequences, including automotive and product-style video ideas.','DRONE / ACTION / CINEMATIC VIDEO']};
 function showGear(key){const [number,title,body,tag]=gear[key];$('#gear-detail').innerHTML=`<span class="gear-number">${number}</span><h3>${title}</h3><p>${body}</p><span class="eyebrow">${tag}</span>`;animateSwap($('#gear-detail'))}
 $$('[data-gear]').forEach(b=>b.addEventListener('click',()=>{selectButtons('[data-gear]',b);showGear(b.dataset.gear)}));showGear('body');
}
// CODE WORLD
if($('#terminal-form')){
 const output=$('#terminal-output'),input=$('#terminal-input');let history=[],historyIndex=0;
 const answers={help:'Available commands:\n  whoami    Meet Tom\n  skills    Languages & tools\n  projects  What’s on the workbench\n  why       The common thread\n  outside   The life beyond the keyboard\n  camera    Behind the lens\n  clear     Clear this terminal\n\nUse ↑ and ↓ to revisit your commands.',whoami:'Tom Williams.\nComputer science student at SUNY Poly.\nPreviously: computer application programming at MVCC.\nDeveloper, photographer, and outdoors person from Upstate New York.',skills:'LANGUAGES\nPython · C++ · Java · JavaScript · HTML/CSS · C#\n\nPROJECT TOOLKIT\nNext.js · MapLibre · Supabase\n\nCREATIVE TOOLKIT\nLightroom · Photoshop · Sony A6700\n\nAlways learning. Usually by building.',projects:'ON THE WORKBENCH\n01  Explore NY — maps, places, trips, and collections\n02  GalleryX — a desktop photo and video organizer\n03  Six islands — a cooperative Minecraft concept\n\nScroll down to open the project notes or play with the island model.',why:'The same curiosity keeps showing up.\n\nA growing photo library becomes an app idea.\nA place worth exploring becomes a map project.\nA game becomes an experiment in cooperation.\n\nI like figuring things out—and making something useful along the way.',outside:'Fishing. Boating. Backpacking. Camping.\n\nDelta Lake and the Adirondacks are part of the picture.\nThe Off the Grid page is where those field notes live.',camera:'Sony A6700, a few different lenses, and a lot to learn.\nWildlife, cars, landscapes, and cinematic video.\n\nVisit Behind the Lens to explore the kit and try the editing playground.'};
 function addLine(text,cls=''){const p=document.createElement('p');p.textContent=text;p.className=cls;output.append(p);while(output.children.length>80)output.firstElementChild.remove();output.scrollTop=output.scrollHeight}
 function run(raw){const command=raw.trim().toLowerCase();if(!command)return;history.push(raw.trim());historyIndex=history.length;if(command==='clear'){output.replaceChildren();addLine('Terminal cleared. Type help whenever you need it.','terminal-muted')}else{addLine('tom ~ $ '+raw.trim(),'terminal-command');addLine((window.Tom?.command(raw.trim())??answers[command])||`Command not found: ${raw.trim()}\nTry help, whoami, skills, projects, why, outside, camera, or clear.`)}input.value=''}
 $('#terminal-form').addEventListener('submit',e=>{e.preventDefault();run(input.value)});$$('[data-command]').forEach(b=>b.addEventListener('click',()=>run(b.dataset.command)));input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);input.value=history[historyIndex]||''}else if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(history.length,historyIndex+1);input.value=history[historyIndex]||''}});
 $$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selectButtons('[data-filter]',b);let count=0;$$('[data-category]').forEach(tile=>{tile.hidden=b.dataset.filter!=='all'&&tile.dataset.category!==b.dataset.filter;if(!tile.hidden){count++;animateSwap(tile)}});$('#project-count').textContent=`${count} project${count===1?'':'s'} on the workbench`;}));
 const islandNames=['Timber','Quarry','Harvest','Forge','Crystal','Harbor'];const resources=['wood','stone','food','iron','diamonds','fishing supplies'];const colors=['#d8f66e','#7dd3fc','#efb38b','#d4b1ed','#f1de8d','#92d9b5'];let selected=0;let owners=[];
 function inspect(){const owner=owners[selected];const partner=owners.findIndex(x=>x!==owner);const tradeText=partner<0?'One player owns all six islands. Bring in more players to see how uneven resources create a reason to trade.':`Player ${owner+1} has access to ${resources[selected]} here. ${islandNames[partner]} belongs to Player ${owners[partner]+1} and offers ${resources[partner]}. That difference creates a reason to trade. Access to another player’s island still needs their permission.`;$('#island-inspector').replaceChildren();const h=document.createElement('h3');h.textContent=`${islandNames[selected]} / Player ${owner+1}`;const para=document.createElement('p');para.textContent=tradeText;$('#island-inspector').append(h,para);$$('.island-tile').forEach((b,i)=>{b.classList.toggle('selected',i===selected);b.setAttribute('aria-pressed',String(i===selected))});}
 function islands(){const players=Number($('#players').value);owners=Array.from({length:6},(_,i)=>i%players);$('#island-board').innerHTML=islandNames.map((name,i)=>`<button class="island-tile" data-island="${i}" style="--owner:${colors[owners[i]]}" aria-pressed="false"><span>ISLAND 0${i+1} · PLAYER ${owners[i]+1}</span><strong>${name}</strong><small>${resources[i].toUpperCase()}</small></button>`).join('');$$('[data-island]').forEach(b=>b.addEventListener('click',()=>{selected=Number(b.dataset.island);inspect()}));inspect();}
 $('#players').addEventListener('change',islands);islands();
}
// OUTDOOR WORLD
if($('#field-detail')){
 const places={delta:['01','Delta Lake','My familiar water. Fishing for bass and pickerel, working out a presentation, and finding a new angle to photograph.','The boat is a 16-foot aluminum MirroCraft Deep-V with a Yamaha 30 hp two-stroke. It gives me plenty of reasons to learn about boating and plenty of projects to tinker with.','FISHING / BOATING / CAMERA ALONG FOR THE RIDE'],adk:['02','The Adirondacks','Trails, lakes, forest, and the feeling that there’s always another place worth seeing. Hiking and backpacking put me closer to the things I like photographing.','I’m drawn to a small camp and a good trail. The trip itself is part of the appeal, from sorting the gear to making something out of the photos and footage afterward.','HIKING / BACKPACKING / LANDSCAPES'],camp:['03','Camp life','A simple meal, a fire, and time to actually be there. Camping slows everything down enough to enjoy the people and place around me.','The kit includes a NEMO Hornet OSMO tent, a REI Flash 55 pack, and a Jetboil. I enjoy figuring out the setup almost as much as using it.','CAMPING / GOOD COMPANY / SMALL DETAILS']};
 function place(key){const [n,title,a,b,tag]=places[key];$('#field-detail').innerHTML=`<span class="field-number">${n}</span><h3>${title}</h3><p>${a}</p><p>${b}</p><div class="field-tag">${tag}</div>`;animateSwap($('#field-detail'));}
 $$('[data-place]').forEach(b=>b.addEventListener('click',()=>{selectButtons('[data-place]',b);place(b.dataset.place)}));place('delta');
 const packs={day:[['water','Water & GRAYL purifier'],['rain','Rain jacket'],['aid','First-aid kit'],['light','NU25 headlamp'],['power','Anker power bank'],['camera','Camera']],night:[['pack','REI Flash 55 pack'],['tent','NEMO Hornet OSMO + footprint'],['sleep','Sleep setup & pillow'],['cook','Jetboil Flash'],['water','Water & GRAYL purifier'],['rain','Rain jacket & pants'],['aid','First-aid kit'],['light','NU25 headlamp'],['power','Anker power bank'],['food','Food & bear canister']],photo:[['camera','Sony A6700'],['wide','Wide or everyday lens'],['tele','Telephoto lens for wildlife'],['tripod','Tripod'],['power','Power bank & charging gear'],['water','Water'],['rain','Rain jacket']]};
 let pack='day';const checked=new Set();
 function count(){const entries=packs[pack],n=entries.filter(([id])=>checked.has(id)).length;$('#packed-number').textContent=n;$('#packed-total').textContent='/ '+entries.length;$('#packed-bar').style.width=n/entries.length*100+'%';$('#packed-message').textContent=n===entries.length?'This kit is checked. The horizon is calling.':n===0?'Every adventure starts somewhere.':`${entries.length-n} more item${entries.length-n===1?'':'s'} in this kit.`;}
 function renderPack(){$('#pack-list').replaceChildren();packs[pack].forEach(([id,name])=>{const label=document.createElement('label'),input=document.createElement('input'),span=document.createElement('span');input.type='checkbox';input.checked=checked.has(id);span.textContent=name;input.addEventListener('change',()=>{input.checked?checked.add(id):checked.delete(id);count()});label.append(input,span);$('#pack-list').append(label)});count();}
 $$('[data-pack]').forEach(b=>b.addEventListener('click',()=>{pack=b.dataset.pack;selectButtons('[data-pack]',b);renderPack()}));$('#reset-pack').addEventListener('click',()=>{packs[pack].forEach(([id])=>checked.delete(id));renderPack()});renderPack();
}
})();
